import { createReadStream } from "fs";
import { stat } from "fs/promises";
import path from "path";
import { Readable } from "stream";
import { NextResponse } from "next/server";

// Serves files uploaded to the Railway Volume. Names are generated by the
// upload route, so anything else is rejected before touching the disk.
const FILE_NAME = /^[0-9a-f-]{36}\.(jpg|png|webp|mp4)$/;

const CONTENT_TYPES: Record<string, string> = {
  jpg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  mp4: "video/mp4",
};

function uploadDir(): string | null {
  const mount = process.env.RAILWAY_VOLUME_MOUNT_PATH;
  return process.env.UPLOAD_DIR ?? (mount ? path.join(mount, "uploads") : null);
}

export async function GET(req: Request, { params }: { params: Promise<{ name: string }> }) {
  const { name } = await params;
  const dir = uploadDir();
  if (!dir || !FILE_NAME.test(name)) return new NextResponse("Not found", { status: 404 });

  const file = path.join(dir, name);
  const info = await stat(file).catch(() => null);
  if (!info?.isFile()) return new NextResponse("Not found", { status: 404 });

  const headers: Record<string, string> = {
    "Content-Type": CONTENT_TYPES[name.split(".").pop() as string] as string,
    "Accept-Ranges": "bytes",
    "Cache-Control": "public, max-age=31536000, immutable",
    "X-Content-Type-Options": "nosniff",
  };

  // Browsers request byte ranges to play and seek through videos
  const range = req.headers.get("range")?.match(/^bytes=(\d*)-(\d*)$/);
  if (range && (range[1] || range[2])) {
    const start = range[1] ? Number(range[1]) : Math.max(0, info.size - Number(range[2]));
    const end = range[1] && range[2] ? Math.min(Number(range[2]), info.size - 1) : info.size - 1;
    if (start >= info.size || start > end) {
      return new NextResponse(null, { status: 416, headers: { "Content-Range": `bytes */${info.size}` } });
    }
    return new NextResponse(Readable.toWeb(createReadStream(file, { start, end })) as ReadableStream, {
      status: 206,
      headers: {
        ...headers,
        "Content-Range": `bytes ${start}-${end}/${info.size}`,
        "Content-Length": String(end - start + 1),
      },
    });
  }

  return new NextResponse(Readable.toWeb(createReadStream(file)) as ReadableStream, {
    headers: { ...headers, "Content-Length": String(info.size) },
  });
}
